const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const create_button = require('button')
const btc_input_card = require('btc_input_card')
const templates = require('templates')

module.exports = send_btc

async function send_btc(opts = {}, callbacks = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const onSend = callbacks.onSend || null
  const onClose = callbacks.onClose || null

  const on = {
    style: inject,
    data: ondata,
    icons: iconject,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  let dricons = []

  shadow.innerHTML = `
    <div class="create-invoice-container">
      <div class="create-invoice-header">  
        <div class="title-container"> 
          <div class="create-invoice-title">Send BTC</div>
          <div class="btc-icon"></div>
        </div>  
        <div class="x-icon"></div>
      </div>

      <!-- Address field — always rendered inline, no STATE dependency -->
      <div class="address-section">
        <div class="address-label">Address</div>
        <div class="address-input-wrapper">
          <input
            type="text"
            class="address-input-field"
            placeholder="Tap to paste recipient address..."
            autocomplete="off"
            spellcheck="false"
          />
          <button class="paste-btn" title="Paste from clipboard">Paste</button>
        </div>
      </div>

      <div class="btc-input-card"></div>
      <div class="divider">
        <div class="sub-divider"></div>
        <div class="divider-text">Or use a template</div>
        <div class="sub-divider"></div>
      </div>
      <div class="templates-heading">Recent Sends</div>
      <div class="templates-list">
        <div class="template1"></div>
        <div class="template2"></div>
        <div class="template3"></div>
        <div class="no-templates-msg" style="display:none; text-align:center; color:#999; font-size:13px; padding:8px 0;">No recent transactions yet</div>
      </div>
      <div class="create_button"></div>
      <div class="send-status"></div>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const create_button_component = shadow.querySelector('.create_button')
  const btc_input_card_component = shadow.querySelector('.btc-input-card')
  const template1_container = shadow.querySelector('.template1')
  const template2_container = shadow.querySelector('.template2')
  const template3_container = shadow.querySelector('.template3')
  const noTemplatesMsg = shadow.querySelector('.no-templates-msg')
  const addressField = shadow.querySelector('.address-input-field')
  const pasteBtn = shadow.querySelector('.paste-btn')
  const statusEl = shadow.querySelector('.send-status')

  // ---- Paste button ----
  pasteBtn.onclick = async () => {
    try {
      if (navigator.clipboard && navigator.clipboard.readText) {
        const text = await navigator.clipboard.readText()
        addressField.value = text.trim()
      }
    } catch (err) {
      console.warn('[send_btc] clipboard read failed:', err)
    }
  }

  const subs = await sdb.watch(onbatch)

  const button_component = subs[0] ? await create_button(subs[0]) : null
  const btc_component = subs[1] ? await btc_input_card(subs[1]) : null
  const templates_component1 = subs[2] ? await templates(subs[2]) : null
  const templates_component2 = subs[3] ? await templates(subs[3]) : null
  const templates_component3 = subs[4] ? await templates(subs[4]) : null

  if (button_component) create_button_component.append(button_component)
  if (btc_component) btc_input_card_component.append(btc_component)
  if (templates_component1) template1_container.append(templates_component1)
  if (templates_component2) template2_container.append(templates_component2)
  if (templates_component3) template3_container.append(templates_component3)

  // Show "no templates" if all three are absent
  _refreshTemplateVisibility()

  // ---- Close button ----
  const closeBtn = shadow.querySelector('.x-icon')
  if (closeBtn) {
    closeBtn.onclick = () => {
      if (onClose) {
        onClose()
      } else {
        const dropdown = el.parentNode
        if (dropdown) dropdown.classList.add('hidden')
      }
    }
  }

  // ---- Send button ----
  if (button_component) {
    button_component.onclick = () => {
      const address = addressField ? addressField.value.trim() : ''
      const amount = btc_component ? btc_component.getAmount() : 0

      _clearStatus()

      if (!address) {
        _setStatus('❌ Address is required', 'error')
        addressField && addressField.focus()
        return
      }
      if (!amount || amount <= 0) {
        _setStatus('❌ Amount must be greater than 0', 'error')
        return
      }

      _setStatus('⏳ Sending transaction…', 'pending')

      if (typeof onSend === 'function') {
        onSend(address, amount)
      }
    }
  }

  // ---- Template click handlers — fill BTC amount ----
  if (templates_component1 && btc_component) {
    templates_component1.onclick = () => _fillFromTemplate(0)
  }
  if (templates_component2 && btc_component) {
    templates_component2.onclick = () => _fillFromTemplate(1)
  }
  if (templates_component3 && btc_component) {
    templates_component3.onclick = () => _fillFromTemplate(2)
  }

  // Store live template amounts so onclick can read them
  let _templateAmounts = [0, 0, 0]

  function _fillFromTemplate(idx) {
    const amt = _templateAmounts[idx]
    if (amt && btc_component) btc_component.setAmount(amt)
  }

  // ---- Public API ----

  // Called by action_buttons when home_contents pushes real balance
  el.updateBalance = function (balance) {
    if (btc_component && typeof btc_component.updateBalance === 'function') {
      btc_component.updateBalance(balance)
    }
  }

  // Called by action_buttons when home_contents pushes real BTC tx history
  // txArray: [{ tid, ttime, tamount, dateString, txid, ... }, ...]
  el.updateTemplates = function (txArray) {
    if (!Array.isArray(txArray)) return

    // Pick up to 3 recent *send* transactions (category === 'send')
    const sends = txArray
      .filter(tx => tx.category === 'send' || (tx.tamount && tx.tamount.toString().trim().startsWith('-') && tx.category !== 'generate'))
      .slice(0, 3)

    _templateAmounts = [0, 0, 0]

    const containers = [template1_container, template2_container, template3_container]
    const components = [templates_component1, templates_component2, templates_component3]

    sends.forEach((tx, i) => {
      const rawAmt = parseFloat(tx.tamount.replace(/[^0-9.]/g, '')) || 0
      _templateAmounts[i] = rawAmt

      // Build a human-readable label: check label, description, tag, or fallback to 'Payment'
      let label = tx.label && tx.label.trim()
        ? tx.label.trim()
        : tx.description && tx.description.trim()
          ? tx.description.trim()
          : tx.tag && tx.tag.trim()
            ? tx.tag.trim()
            : ''
      const systemLabels = ['miner-reward', 'miner reward', 'bctr', 'coinbase', 'unknown']
      if (!label || systemLabels.some(sys => label.toLowerCase().includes(sys)) || label.length > 20) {
        label = 'Payment'
      }

      // Use the public _update() API exposed by the templates component
      if (components[i] && typeof components[i]._update === 'function') {
        components[i]._update(tx, rawAmt, label)
      }
    })

    // Hide unused template slots
    for (let i = sends.length; i < 3; i++) {
      containers[i].style.display = 'none'
    }
    // Show used slots
    for (let i = 0; i < sends.length; i++) {
      containers[i].style.display = ''
    }

    _refreshTemplateVisibility(sends.length)
  }

  // Called by action_buttons after backend responds to send_btc_onchain
  el.onPaymentSent = function ({ success, error, txid }) {
    if (success) {
      _setStatus(`✅ Sent! TXID: ${(txid || '').substring(0, 18)}…`, 'success')
      addressField.value = ''
      if (btc_component) btc_component.setAmount(0)
      setTimeout(() => {
        _clearStatus()
        if (onClose) onClose()
      }, 2500)
    } else {
      _setStatus(`❌ Error: ${error || 'Unknown error'}`, 'error')
    }
  }

  return el

  // ---- Internal helpers ----

  function _setStatus(msg, type) {
    statusEl.textContent = msg
    statusEl.className = 'send-status send-status--' + type
  }

  function _clearStatus() {
    statusEl.textContent = ''
    statusEl.className = 'send-status'
  }

  function _refreshTemplateVisibility(count) {
    const hasTemplates = count === undefined
      ? (templates_component1 || templates_component2 || templates_component3)
      : count > 0
    noTemplatesMsg.style.display = hasTemplates ? 'none' : 'block'
  }

  function _getDateLabel(dateString) {
    if (!dateString) return 'Unknown'
    try {
      const today = new Date()
      const target = new Date(dateString)
      const diff = Math.floor(
        (today.setHours(0, 0, 0, 0) - target.setHours(0, 0, 0, 0)) / 86400000
      )
      if (diff === 0) return 'Today'
      if (diff === 1) return 'Yesterday'
      return target.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    } catch {
      return dateString
    }
  }

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw)))
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function iconject(data) {
    dricons = data

    const btc_icon = shadow.querySelector('.btc-icon')
    const x_icon = shadow.querySelector('.x-icon')

    if (btc_icon) btc_icon.innerHTML = dricons[0] || ''
    if (x_icon) x_icon.innerHTML = dricons[1] || '✖'
  }

  async function ondata(data) {
    // Reserved for future STATE-pushed data
  }
}

function fallback_module() {
  return {
    api,
    _: {
      'button': { $: '' },
      'btc_input_card': { $: '' },
      'templates': { $: '' },
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const button = {
      mapping: {
        style: 'style',
        data: 'data',
      },
      0: {
        label: 'Send'
      }
    }

    const btc_input_card = {
      mapping: {
        style: 'style',
        data: 'data',
      },
      1: {
        balance: 0,
      }
    }

    const templates = {
      mapping: {
        style: 'style',
        data: 'data',
        icons: 'icons'
      },
      // Three template slots — data populated at runtime by updateTemplates()
      2: {
        date: new Date().toISOString().split('T')[0],
        btc: 0,
        usd: 0
      },
      3: {
        date: new Date().toISOString().split('T')[0],
        btc: 0,
        usd: 0
      },
      4: {
        date: new Date().toISOString().split('T')[0],
        btc: 0,
        usd: 0
      }
    }

    return {
      drive: {
        'icons/': {
          'btc.svg': {
            '$ref': 'btc.svg'
          },
          'x.svg': {
            '$ref': 'x.svg'
          },
        },
        'style/': {
          'send_btc.css': {
            '$ref': 'send_btc.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          }
        }
      },
      _: {
        button,
        btc_input_card,
        templates,
      }
    }
  }
}
